17	// A node could either be a leader or a follower
18	const (
19		Leader   Role = false
20		Follower Role = true
21	)
22	
23	//go:generate mockery -dir . -name HeartbeatEventHandler -case underscore -output ./mocks/
24	
25	// HeartbeatEventHandler defines who to call when a heartbeat timeout expires or a Sync needs to be triggered.
26	// This is implemented by the Controller.
27	type HeartbeatEventHandler interface {
28		// OnHeartbeatTimeout is called when a heartbeat timeout expires.
29		OnHeartbeatTimeout(view uint64, leaderID uint64)
30		// Sync is called when enough heartbeat responses report that the current leader's view is outdated.
31		Sync()
32	}
33	
34	// Role indicates if this node is a follower or a leader
35	type Role bool
36	
37	type roleChange struct {
38		view                            uint64
39		leaderID                        uint64
40		follower                        Role
41		onlyStopSendHeartbearFromLeader bool
42	}
43	
44	// heartbeatResponseCollector is a map from node ID to view number, and hold the last response from each node.
45	type heartbeatResponseCollector map[uint64]uint64
46	
47	// HeartbeatMonitor implements LeaderMonitor
48	type HeartbeatMonitor struct {
49		scheduler                     <-chan time.Time
50		inc                           chan incMsg
51		stopChan                      chan struct{}
52		commandChan                   chan roleChange
53		logger                        api.Logger
54		hbTimeout                     time.Duration
55		hbCount                       uint64
56		comm                          Comm
57		numberOfNodes                 uint64
58		SelfID                        uint64
59		handler                       HeartbeatEventHandler
60		view                          uint64
61		leaderID                      uint64
62		follower                      Role
63		stopSendHeartbearFromLeader   bool
64		lastHeartbeat                 time.Time
65		lastTick                      time.Time
66		hbRespCollector               heartbeatResponseCollector
67		running                       sync.WaitGroup
68		runOnce                       sync.Once
69		timedOut                      bool
70		syncReq                       bool
71		viewSequences                 *atomic.Value
72		sentHeartbeat                 chan struct{}
73		artificialHeartbeat           chan incMsg
74		behindSeq                     uint64
75		behindCounter                 uint64
76		numOfTicksBehindBeforeSyncing uint64
77		followerBehind                bool
78	}
79	
80	// NewHeartbeatMonitor creates a new HeartbeatMonitor
81	func NewHeartbeatMonitor(scheduler <-chan time.Time, logger api.Logger, heartbeatTimeout time.Duration, heartbeatCount uint64, comm Comm, numberOfNodes uint64, handler HeartbeatEventHandler, viewSequences *atomic.Value, numOfTicksBehindBeforeSyncing uint64) *HeartbeatMonitor {
82		hm := &HeartbeatMonitor{
83			stopChan:                      make(chan struct{}),
84			inc:                           make(chan incMsg),
85			commandChan:                   make(chan roleChange),
86			scheduler:                     scheduler,
87			logger:                        logger,
88			hbTimeout:                     heartbeatTimeout,
89			hbCount:                       heartbeatCount,
90			comm:                          comm,
91			numberOfNodes:                 numberOfNodes,
92			handler:                       handler,
93			hbRespCollector:               make(heartbeatResponseCollector),
94			viewSequences:                 viewSequences,
95			sentHeartbeat:                 make(chan struct{}, 1),
96			artificialHeartbeat:           make(chan incMsg, 1),
97			numOfTicksBehindBeforeSyncing: numOfTicksBehindBeforeSyncing,
98		}
99		return hm
100	}
101	
102	func (hm *HeartbeatMonitor) start() {
103		hm.running.Add(1)
104		go hm.run()
105	}
106	
107	// Close stops following or sending heartbeats.
108	func (hm *HeartbeatMonitor) Close() {
109		if hm.closed() {
110			return
111		}
112		defer func() {
113			hm.lastHeartbeat = time.Time{}
114			hm.lastTick = time.Time{}
115		}()
116		defer hm.running.Wait()
117		close(hm.stopChan)
118	}
119	
120	func (hm *HeartbeatMonitor) run() {
121		defer hm.running.Done()
122		for {
123			select {
124			case <-hm.stopChan:
125				return
126			case now := <-hm.scheduler:
127				hm.tick(now)
128			case msg := <-hm.inc:
129				hm.handleMsg(msg.sender, msg.Message)
130			case cmd := <-hm.commandChan:
131				hm.handleCommand(cmd)
132			case <-hm.sentHeartbeat:
133				hm.lastHeartbeat = hm.lastTick
134			case msg := <-hm.artificialHeartbeat:
135				hm.handleArtificialHeartBeat(msg.sender, msg.GetHeartBeat())
136			}
137		}
138	}
139	
140	// ProcessMsg handles an incoming heartbeat or heartbeat-response.
141	// If the sender and msg.View equal what we expect, and the timeout had not expired yet, the timeout is extended.
142	func (hm *HeartbeatMonitor) ProcessMsg(sender uint64, msg *smartbftprotos.Message) {
143		select {
144		case hm.inc <- incMsg{
145			sender:  sender,
146			Message: msg,
147		}:
148		case <-hm.stopChan:
149		}
150	}
151	
152	// InjectArtificialHeartbeat injects an artificial heartbeat to the monitor
153	func (hm *HeartbeatMonitor) InjectArtificialHeartbeat(sender uint64, msg *smartbftprotos.Message) {
154		select {
155		case hm.artificialHeartbeat <- incMsg{
156			sender:  sender,
157			Message: msg,
158		}:
159		default:
160		}
161	}
162	
163	func (hm *HeartbeatMonitor) StopLeaderSendMsg() {
164		hm.logger.Infof("Changing role to follower without change current view and current leader")
165		select {
166		case hm.commandChan <- roleChange{
167			onlyStopSendHeartbearFromLeader: true,
168		}:
169		case <-hm.stopChan:
170			return
171		}
172	}
173	
174	// ChangeRole will change the role of this HeartbeatMonitor
175	func (hm *HeartbeatMonitor) ChangeRole(follower Role, view uint64, leaderID uint64) {
176		hm.runOnce.Do(func() {
177			hm.follower = follower
178			hm.start()
179		})
180	
181		role := "leader"
182		if follower {
183			role = "follower"
184		}
185	
186		hm.logger.Infof("Changing to %s role, current view: %d, current leader: %d", role, view, leaderID)
187		select {
188		case hm.commandChan <- roleChange{
189			leaderID: leaderID,
190			view:     view,
191			follower: follower,
192		}:
193		case <-hm.stopChan:
194			return
195		}
196	}
197	
198	func (hm *HeartbeatMonitor) handleMsg(sender uint64, msg *smartbftprotos.Message) {
199		switch msg.GetContent().(type) {
200		case *smartbftprotos.Message_HeartBeat:
201			hm.handleRealHeartBeat(sender, msg.GetHeartBeat())
202		case *smartbftprotos.Message_HeartBeatResponse:
203			hm.handleHeartBeatResponse(sender, msg.GetHeartBeatResponse())
204		default:
205			hm.logger.Warnf("Unexpected message type, ignoring")
206		}
207	}
208	
209	func (hm *HeartbeatMonitor) handleRealHeartBeat(sender uint64, hb *smartbftprotos.HeartBeat) {
210		hm.handleHeartBeat(sender, hb, false)
211	}
212	
213	func (hm *HeartbeatMonitor) handleArtificialHeartBeat(sender uint64, hb *smartbftprotos.HeartBeat) {
214		hm.handleHeartBeat(sender, hb, true)
215	}
216	
217	func (hm *HeartbeatMonitor) handleHeartBeat(sender uint64, hb *smartbftprotos.HeartBeat, artificial bool) {
218		if hb.View < hm.view {
219			hm.logger.Debugf("Heartbeat view is lower than expected, sending response; expected-view=%d, received-view: %d", hm.view, hb.View)
220			hm.sendHeartBeatResponse(sender)
221			return
222		}
223	
224		if !hm.stopSendHeartbearFromLeader && sender != hm.leaderID {
225			hm.logger.Debugf("Heartbeat sender is not leader, ignoring; leader: %d, sender: %d", hm.leaderID, sender)
226			return
227		}
228	
229		if hb.View > hm.view {
230			hm.logger.Debugf("Heartbeat view is bigger than expected, syncing and ignoring; expected-view=%d, received-view: %d", hm.view, hb.View)
231			hm.handler.Sync()
232			return
233		}
234	
235		active, ourSeq := hm.viewActive(hb)
236		if active && !artificial {
237			if ourSeq+1 < hb.Seq {
238				hm.logger.Debugf("Heartbeat sequence is bigger than expected, leader's sequence is %d and ours is %d, syncing and ignoring", hb.Seq, ourSeq)
239				hm.handler.Sync()
240				return
241			}
242			if ourSeq+1 == hb.Seq {
243				hm.followerBehind = true
244				hm.logger.Debugf("Our sequence is behind the heartbeat sequence, leader's sequence is %d and ours is %d", hb.Seq, ourSeq)
245				if ourSeq > hm.behindSeq {
246					hm.behindSeq = ourSeq
247					hm.behindCounter = 0
248				}
249			} else {
250				hm.followerBehind = false
251			}
252		} else {
253			hm.followerBehind = false
254		}
255	
256		hm.logger.Debugf("Received heartbeat from %d, last heartbeat was %v ago", sender, hm.lastTick.Sub(hm.lastHeartbeat))
257		hm.lastHeartbeat = hm.lastTick
258	}
259	
260	// handleHeartBeatResponse keeps track of responses, and if we get f+1 identical, force a sync
261	func (hm *HeartbeatMonitor) handleHeartBeatResponse(sender uint64, hbr *smartbftprotos.HeartBeatResponse) {
262		if hm.follower {
263			hm.logger.Debugf("Monitor is not a leader, ignoring HeartBeatResponse; sender: %d, msg: %v", sender, hbr)
264			return
265		}
266	
267		if hm.syncReq {
268			hm.logger.Debugf("Monitor already called Sync, ignoring HeartBeatResponse; sender: %d, msg: %v", sender, hbr)
269			return
270		}
271	
272		if hm.view >= hbr.View {
273			hm.logger.Debugf("Monitor view: %d >= HeartBeatResponse, ignoring; sender: %d, msg: %v", hm.view, sender, hbr)
274			return
275		}
276	
277		hm.logger.Debugf("Received HeartBeatResponse, msg: %v; from %d", hbr, sender)
278		hm.hbRespCollector[sender] = hbr.View
279	
280		// check if we have f+1 votes
281		_, f := computeQuorum(hm.numberOfNodes)
282		if len(hm.hbRespCollector) >= f+1 {
283			hm.logger.Infof("Received HeartBeatResponse triggered a call to HeartBeatEventHandler Sync, view: %d", hbr.View)
284			hm.handler.Sync()
285			hm.syncReq = true
286		}
287	}
