289	func (hm *HeartbeatMonitor) sendHeartBeatResponse(target uint64) {
290		heartbeatResponse := &smartbftprotos.Message{
291			Content: &smartbftprotos.Message_HeartBeatResponse{
292				HeartBeatResponse: &smartbftprotos.HeartBeatResponse{
293					View: hm.view,
294				},
295			},
296		}
297		hm.comm.SendConsensus(target, heartbeatResponse)
298		hm.logger.Debugf("Sent HeartBeatResponse view: %d; to %d", hm.view, target)
299	}
300	
301	func (hm *HeartbeatMonitor) viewActive(hbMsg *smartbftprotos.HeartBeat) (bool, uint64) {
302		vs := hm.viewSequences.Load()
303		// View isn't initialized
304		if vs == nil {
305			return false, 0
306		}
307	
308		viewSeq := vs.(ViewSequence)
309		if !viewSeq.ViewActive {
310			return false, 0
311		}
312	
313		return true, viewSeq.ProposalSeq
314	}
315	
316	func (hm *HeartbeatMonitor) tick(now time.Time) {
317		hm.lastTick = now
318		if hm.lastHeartbeat.IsZero() {
319			hm.lastHeartbeat = now
320		}
321		if bool(hm.follower) || hm.stopSendHeartbearFromLeader {
322			hm.followerTick(now)
323		} else {
324			hm.leaderTick(now)
325		}
326	}
327	
328	func (hm *HeartbeatMonitor) closed() bool {
329		select {
330		case <-hm.stopChan:
331			return true
332		default:
333			return false
334		}
335	}
336	
337	func (hm *HeartbeatMonitor) handleCommand(cmd roleChange) {
338		if cmd.onlyStopSendHeartbearFromLeader {
339			hm.stopSendHeartbearFromLeader = true
340			return
341		}
342	
343		hm.stopSendHeartbearFromLeader = false
344		hm.view = cmd.view
345		hm.leaderID = cmd.leaderID
346		hm.follower = cmd.follower
347		hm.timedOut = false
348		hm.lastHeartbeat = hm.lastTick
349		hm.hbRespCollector = make(heartbeatResponseCollector)
350		hm.syncReq = false
351		if TLATrace != nil {
352			role := "follower"
353			if !hm.follower {
354				role = "leader"
355			}
356			TLATrace.Emit(map[string]interface{}{
357				"event":  "change_role",
358				"node":   hm.SelfID,
359				"view":   hm.view,
360				"leader": hm.leaderID,
361				"role":   role,
362			})
363		}
364	}
365	
366	func (hm *HeartbeatMonitor) leaderTick(now time.Time) {
367		if now.Sub(hm.lastHeartbeat)*time.Duration(hm.hbCount) < hm.hbTimeout {
368			return
369		}
370	
371		var sequence uint64
372		vs := hm.viewSequences.Load()
373		if vs != nil && vs.(ViewSequence).ViewActive {
374			sequence = vs.(ViewSequence).ProposalSeq
375		} else {
376			hm.logger.Infof("ViewSequence uninitialized or view inactive")
377			return
378		}
379		hm.logger.Debugf("Sending heartbeat with view %d, sequence %d", hm.view, sequence)
380		heartbeat := &smartbftprotos.Message{
381			Content: &smartbftprotos.Message_HeartBeat{
382				HeartBeat: &smartbftprotos.HeartBeat{
383					View: hm.view,
384					Seq:  sequence,
385				},
386			},
387		}
388		hm.comm.BroadcastConsensus(heartbeat)
389		hm.lastHeartbeat = now
390	}
391	
392	func (hm *HeartbeatMonitor) followerTick(now time.Time) {
393		if hm.timedOut || hm.lastHeartbeat.IsZero() {
394			hm.lastHeartbeat = now
395			return
396		}
397	
398		delta := now.Sub(hm.lastHeartbeat)
399		if delta >= hm.hbTimeout {
400			hm.logger.Warnf("Heartbeat timeout (%v) from %d expired; last heartbeat was observed %s ago",
401				hm.hbTimeout, hm.leaderID, delta)
402			if TLATrace != nil {
403				TLATrace.Emit(map[string]interface{}{
404					"event":                "hb_timeout",
405					"node":                 hm.SelfID,
406					"view":                 hm.view,
407					"leader":               hm.leaderID,
408					"hbm_timed_out_before": hm.timedOut,
409				})
410			}
411			hm.handler.OnHeartbeatTimeout(hm.view, hm.leaderID)
412			hm.timedOut = true
413			return
414		}
415	
416		hm.logger.Debugf("Last heartbeat from %d was %v ago", hm.leaderID, delta)
417	
418		if !hm.followerBehind {
419			return
420		}
421	
422		hm.behindCounter++
423		if hm.behindCounter >= hm.numOfTicksBehindBeforeSyncing {
424			hm.logger.Warnf("Syncing since the follower with seq %d is behind the leader for the last %d ticks", hm.behindSeq, hm.numOfTicksBehindBeforeSyncing)
425			hm.handler.Sync()
426			hm.behindCounter = 0
427			return
428		}
429	}
