326	// InformNewView tells the view changer to advance to a new view number
327	func (v *ViewChanger) InformNewView(view uint64) {
328		select {
329		case v.informChan <- view:
330		case <-v.stopChan:
331			return
332		}
333	}
334	
335	func (v *ViewChanger) informNewView(view uint64) {
336		if view < v.currView {
337			v.Logger.Debugf("Node %d was informed of view %d, but the current view is %d", v.SelfID, view, v.currView)
338			return
339		}
340		v.Logger.Debugf("Node %d was informed of a new view %d", v.SelfID, view)
341		v.currView = view
342		v.realView = v.currView
343		v.nextView = v.currView
344		v.MetricsViewChange.CurrentView.Set(float64(v.currView))
345		v.MetricsViewChange.RealView.Set(float64(v.realView))
346		v.MetricsViewChange.NextView.Set(float64(v.nextView))
347		v.nvs.clear()
348		v.viewChangeMsgs.clear(v.N)
349		v.viewDataMsgs.clear(v.N)
350		v.checkTimeout = false
351		v.backOffFactor = 1 // reset
352		v.RequestsTimer.RestartTimers()
353	}
354	
355	// StartViewChange initiates a view change
356	func (v *ViewChanger) StartViewChange(view uint64, stopView bool) {
357		dropped := true
358		select {
359		case v.startChangeChan <- &change{view: view, stopView: stopView}:
360			dropped = false
361		default:
362		}
363		if TLATrace != nil {
364			TLATrace.Emit(map[string]interface{}{
365				"event":     "view_change_start",
366				"node":      v.SelfID,
367				"next_view": view + 1,
368				"dropped":   dropped,
369			})
370		}
371	}
372	
373	// StartViewChange stops current view and timeouts, and broadcasts a view change message to all
374	func (v *ViewChanger) startViewChange(change *change) {
375		if change.view < v.currView { // this is about an old view
376			v.Logger.Debugf("Node %d has a view change request with an old view %d, while the current view is %d", v.SelfID, change.view, v.currView)
377			return
378		}
379		if v.nextView == v.currView+1 {
380			v.Logger.Debugf("Node %d has already started view change with last view %d", v.SelfID, v.currView)
381			v.checkTimeout = true // make sure timeout is checked anyway
382			return
383		}
384		v.nextView = v.currView + 1
385		v.MetricsViewChange.NextView.Set(float64(v.nextView))
386		v.RequestsTimer.StopTimers()
387		msg := &protos.Message{
388			Content: &protos.Message_ViewChange{
389				ViewChange: &protos.ViewChange{
390					NextView: v.nextView,
391				},
392			},
393		}
394		v.Comm.BroadcastConsensus(msg)
395		v.Logger.Debugf("Node %d started view change, last view is %d", v.SelfID, v.currView)
396		if change.stopView {
397			v.Controller.AbortView(v.currView) // abort the current view when joining view change
398		}
399		v.startViewChangeTime = v.lastTick
400		v.checkTimeout = true
401	}
402	
403	func (v *ViewChanger) processViewChangeMsg(restore bool) {
404		if ((uint64(len(v.viewChangeMsgs.voted)) == uint64(v.f+1)) && v.SpeedUpViewChange) || restore { // join view change
405			v.Logger.Debugf("Node %d is joining view change, last view is %d", v.SelfID, v.currView)
406			v.startViewChange(&change{v.currView, true})
407		}
408		if (len(v.viewChangeMsgs.voted) < v.quorum-1) && !restore {
409			return
410		}
411		// send view data
412		if !v.SpeedUpViewChange {
413			v.Logger.Debugf("Node %d is joining view change, last view is %d", v.SelfID, v.currView)
414			v.startViewChange(&change{v.currView, true})
415		}
416		if !restore {
417			msgToSave := &protos.SavedMessage{
418				Content: &protos.SavedMessage_ViewChange{
419					ViewChange: &protos.ViewChange{
420						NextView: v.currView,
421					},
422				},
423			}
424			if err := v.State.Save(msgToSave); err != nil {
425				v.Logger.Panicf("Failed to save message to state, error: %v", err)
426			}
427		}
428		v.Controller.AbortView(v.currView) // before preparing the view data message abort the current view
429		v.currView = v.nextView
430		v.MetricsViewChange.CurrentView.Set(float64(v.currView))
431		v.viewChangeMsgs.clear(v.N)
432		v.viewDataMsgs.clear(v.N) // clear because currView changed
433		msg := v.prepareViewDataMsg()
434		leader := v.getLeader()
435		if leader == v.SelfID {
436			v.viewDataMsgs.registerVote(v.SelfID, msg)
437		} else {
438			v.Comm.SendConsensus(leader, msg)
439		}
440		v.Logger.Debugf("Node %d sent view data msg, with next view %d, to the new leader %d", v.SelfID, v.currView, leader)
441	}
442	
443	func (v *ViewChanger) prepareViewDataMsg() *protos.Message {
444		lastDecision, lastDecisionSignatures := v.Checkpoint.Get()
445		inFlight := v.getInFlight(lastDecision)
446		prepared := v.InFlight.IsInFlightPrepared()
447		vd := &protos.ViewData{
448			NextView:               v.currView,
449			LastDecision:           lastDecision,
450			LastDecisionSignatures: lastDecisionSignatures,
451			InFlightProposal:       inFlight,
452			InFlightPrepared:       prepared,
453		}
454		vdBytes := MarshalOrPanic(vd)
455		sig := v.Signer.Sign(vdBytes)
456		msg := &protos.Message{
457			Content: &protos.Message_ViewData{
458				ViewData: &protos.SignedViewData{
459					RawViewData: vdBytes,
460					Signer:      v.SelfID,
461					Signature:   sig,
462				},
463			},
464		}
465		return msg
466	}
467	
468	func (v *ViewChanger) getInFlight(lastDecision *protos.Proposal) *protos.Proposal {
469		inFlight := v.InFlight.InFlightProposal()
470		if inFlight == nil {
471			v.Logger.Debugf("Node %d's in flight proposal is not set", v.SelfID)
472			return nil
473		}
474		if inFlight.Metadata == nil {
475			v.Logger.Panicf("Node %d's in flight proposal metadata is not set", v.SelfID)
476		}
477		inFlightMetadata := &protos.ViewMetadata{}
478		if err := proto.Unmarshal(inFlight.Metadata, inFlightMetadata); err != nil {
479			v.Logger.Panicf("Node %d is unable to unmarshal its own in flight metadata, err: %v", v.SelfID, err)
480		}
481		proposal := &protos.Proposal{
482			Header:               inFlight.Header,
483			Metadata:             inFlight.Metadata,
484			Payload:              inFlight.Payload,
485			VerificationSequence: uint64(inFlight.VerificationSequence),
486		}
487		if lastDecision == nil {
488			v.Logger.Panicf("%d The given last decision is nil", v.SelfID)
489			return nil
490		}
491		if lastDecision.Metadata == nil {
492			return proposal // this is the first proposal after genesis
493		}
494		lastDecisionMetadata := &protos.ViewMetadata{}
495		if err := proto.Unmarshal(lastDecision.Metadata, lastDecisionMetadata); err != nil {
496			v.Logger.Panicf("Node %d is unable to unmarshal its own last decision metadata from checkpoint, err: %v", v.SelfID, err)
497		}
498		if inFlightMetadata.LatestSequence == lastDecisionMetadata.LatestSequence {
499			v.Logger.Debugf("Node %d's in flight proposal and the last decision has the same sequence: %d", v.SelfID, inFlightMetadata.LatestSequence)
500			return nil // this is not an actual in flight proposal
501		}
502		if inFlightMetadata.LatestSequence+1 == lastDecisionMetadata.LatestSequence && v.committedDuringViewChange != nil &&
503			v.committedDuringViewChange.LatestSequence == lastDecisionMetadata.LatestSequence {
504			v.Logger.Infof("Node %d's in flight proposal sequence is %d while already committed decision %d, "+
505				"but that is because it committed it during the view change", v.SelfID, inFlightMetadata.LatestSequence, lastDecisionMetadata.LatestSequence)
506			return nil
507		}
508		return proposal
509	}
510	
511	func (v *ViewChanger) validateViewDataMsg(svd *protos.SignedViewData, sender uint64) bool {
512		if v.getLeader() != v.SelfID { // check if I am the next leader
513			v.Logger.Warnf("Node %d got %s from %d, but %d is not the next leader of view %d", v.SelfID, signedViewDataToString(svd), sender, v.SelfID, v.currView)
514			return false
515		}
516	
517		vd := &protos.ViewData{}
518		if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
519			v.Logger.Errorf("Node %d was unable to unmarshal viewData message from %d, error: %v", v.SelfID, sender, err)
520			return false
521		}
522		if vd.NextView != v.currView { // check that the message is aligned to this view
523			v.Logger.Warnf("Node %d got %s from %d, but %d is in view %d", v.SelfID, signedViewDataToString(svd), sender, v.SelfID, v.currView)
524			return false
525		}
526	
527		valid, lastDecisionSequence := v.checkLastDecision(svd, sender)
528		if !valid {
529			v.Logger.Warnf("Node %d got %v from %d, but the check of the last decision didn't pass", v.SelfID, signedViewDataToString(svd), sender)
530			return false
531		}
532	
533		v.Logger.Debugf("Node %d got %s from %d, and it passed the last decision check", v.SelfID, signedViewDataToString(svd), sender)
534	
535		if err := ValidateInFlight(vd.InFlightProposal, lastDecisionSequence); err != nil {
536			v.Logger.Warnf("Node %d got %v from %d, but the in flight proposal is invalid, reason: %v", v.SelfID, signedViewDataToString(svd), sender, err)
537			return false
538		}
539	
540		v.Logger.Debugf("Node %d got %s from %d, and the in flight proposal is valid", v.SelfID, signedViewDataToString(svd), sender)
541	
542		return true
543	}
544	
545	func (v *ViewChanger) checkLastDecision(svd *protos.SignedViewData, sender uint64) (valid bool, lastDecisionSequence uint64) {
546		vd := &protos.ViewData{}
547		if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
548			v.Logger.Errorf("Node %d was unable to unmarshal viewData message from %d, error: %v", v.SelfID, sender, err)
549			return false, 0
550		}
551	
552		if vd.LastDecision == nil {
553			v.Logger.Warnf("Node %d got %s from %d, but the last decision is not set", v.SelfID, signedViewDataToString(svd), sender)
554			return false, 0
555		}
556	
557		mySequence, myLastDecision := v.extractCurrentSequence()
558	
559		// Begin to check the last decision within the view data message.
560		//
561		// The sender might be behind, in which case the new leader might not have the right config to validate
562		// the decision and signatures, and so the view data message is deemed invalid.
563		//
564		// If the sender is too far ahead, the new leader might not have the appropriate config.
565		// We do not want the new leader to perform a sync at this point, since the sender might be malicious.
566		// So this message is considered invalid. If the leader is actually behind this view change will eventually timeout.
567		//
568		// If the new leader and the sender have the same last decision sequence then we check that the decisions are equal.
569		// However, we cannot validate the decision signatures since this last decision might have been a reconfig.
570		//
571		// Lastly, the sender is ahead by one sequence, and so the new leader validates the decision and delivers it.
572		// Only after delivery the message signature is verified, again since this decision might have been a reconfig.
573	
574		if vd.LastDecision.Metadata == nil { // this is a genesis proposal
575			if mySequence > 0 {
576				v.Logger.Debugf("Node %d got %s from %d, but the last decision seq (0) is lower than this node's current sequence %d", v.SelfID, signedViewDataToString(svd), sender, mySequence)
577				return false, 0 // this node is ahead
578			}
579			return true, 0
580		}
581		lastDecisionMD := &protos.ViewMetadata{}
582		if err := proto.Unmarshal(vd.LastDecision.Metadata, lastDecisionMD); err != nil {
583			v.Logger.Warnf("Node %d got %s from %d, but was unable to unmarshal last decision metadata, err: %v", v.SelfID, signedViewDataToString(svd), sender, err)
584			return false, 0
585		}
586		if lastDecisionMD.ViewId >= vd.NextView {
587			v.Logger.Warnf("Node %d got %s from %d, but the last decision view %d is greater or equal to requested next view %d", v.SelfID, signedViewDataToString(svd), sender, lastDecisionMD.ViewId, vd.NextView)
588			return false, 0
589		}
590	
591		v.Logger.Debugf("Node %d got %s from %d, the last decision seq is %d and this node's current sequence is %d", v.SelfID, signedViewDataToString(svd), sender, lastDecisionMD.LatestSequence, mySequence)
592	
593		if lastDecisionMD.LatestSequence > mySequence+1 { // this is a decision in the future, ignoring since the node might not have the right configuration to validate
594			v.Logger.Debugf("Node %d got %s from %d, but the last decision seq %d is greater than this node's current sequence %d", v.SelfID, signedViewDataToString(svd), sender, lastDecisionMD.LatestSequence, mySequence)
595			return false, 0
596		}
597		if lastDecisionMD.LatestSequence < mySequence { // this is a decision in the past, ignoring since the node might not have the right configuration to validate
598			v.Logger.Debugf("Node %d got %s from %d, but the last decision seq %d is lower than this node's current sequence %d", v.SelfID, signedViewDataToString(svd), sender, lastDecisionMD.LatestSequence, mySequence)
599			return false, 0
600		}
601	
602		if lastDecisionMD.LatestSequence == mySequence { // just make sure that we have the same last decision, can't verify the signatures of this last decision since this might have been a reconfiguration
603			// the signature on this message can be verified
604			if svd.Signer != sender {
605				v.Logger.Warnf("Node %d got %s from %d, but signer %d is not the sender %d", v.SelfID, signedViewDataToString(svd), sender, svd.Signer, sender)
606				return false, 0
607			}
608			sameSeqSigErr := v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData})
609			if TLATrace != nil {
610				TLATrace.Emit(map[string]interface{}{
611					"event": "vc_same_seq",
612					"node":  v.SelfID,
613					"from":  sender,
614					"seq":   lastDecisionMD.LatestSequence,
615					"view":  v.currView,
616					"valid": sameSeqSigErr == nil,
617				})
618			}
619			if sameSeqSigErr != nil {
620				v.Logger.Warnf("Node %d got %s from %d, but signature is invalid, error: %v", v.SelfID, signedViewDataToString(svd), sender, sameSeqSigErr)
621				return false, 0
622			}
623	
624			// compare the last decision itself
625			if !proto.Equal(vd.LastDecision, myLastDecision) {
626				v.Logger.Warnf("Node %d got %s from %d, they are at the same sequence but the last decisions are not equal", v.SelfID, signedViewDataToString(svd), sender)
627				return false, 0
628			}
629	
630			return true, lastDecisionMD.LatestSequence
631		}
632	
633		if lastDecisionMD.LatestSequence != mySequence+1 {
634			v.Logger.Warnf("Node %d got %s from %d, the last decision sequence is not equal to this node's sequence + 1", v.SelfID, signedViewDataToString(svd), sender)
635			return false, 0
636		}
637	
638		// This node is one sequence behind, validate the last decision and deliver
639	
640		_, err := ValidateLastDecision(vd, v.quorum, v.N, v.Verifier)
641		if err != nil {
642			v.Logger.Warnf("Node %d got %s from %d, but the last decision is invalid, reason: %v", v.SelfID, signedViewDataToString(svd), sender, err)
643			return false, 0
644		}
645	
646		proposal := types.Proposal{
647			Header:               vd.LastDecision.Header,
648			Metadata:             vd.LastDecision.Metadata,
649			Payload:              vd.LastDecision.Payload,
650			VerificationSequence: int64(vd.LastDecision.VerificationSequence),
651		}
652		signatures := make([]types.Signature, 0, len(vd.LastDecisionSignatures))
653		for _, sig := range vd.LastDecisionSignatures {
654			signature := types.Signature{
655				ID:    sig.Signer,
656				Value: sig.Value,
657				Msg:   sig.Msg,
658			}
659			signatures = append(signatures, signature)
660		}
661		v.deliverDecision(proposal, signatures)
662		if TLATrace != nil {
663			TLATrace.Emit(map[string]interface{}{
664				"event": "vc_deliver",
665				"node":  v.SelfID,
666				"from":  sender,
667				"seq":   lastDecisionMD.LatestSequence,
668				"view":  v.currView,
669			})
670		}
671	
672		// Make note that we have advanced the sequence during a view change,
673		// so our in-flight sequence may be behind.
674		md := &protos.ViewMetadata{}
675		if err = proto.Unmarshal(proposal.Metadata, md); err != nil {
676			v.Logger.Panicf("Node %d got %s from %d, but was unable to unmarshal proposal metadata, err: %v", v.SelfID, signedViewDataToString(svd), sender, err)
677		}
678		v.committedDuringViewChange = md
679	
680		select { // if there was a delivery with a reconfig we need to stop here before verify signature
681		case <-v.stopChan:
682			return false, 0
683		default:
684		}
685	
686		if svd.Signer != sender {
687			v.Logger.Warnf("Node %d got %s from %d, but signer %d is not the sender %d", v.SelfID, signedViewDataToString(svd), sender, svd.Signer, sender)
688			return false, 0
689		}
690		vcValSigErr := v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData})
691		if TLATrace != nil {
692			TLATrace.Emit(map[string]interface{}{
693				"event": "vc_validate",
694				"node":  v.SelfID,
695				"from":  sender,
696				"view":  v.currView,
697				"valid": vcValSigErr == nil,
698			})
699		}
700		if vcValSigErr != nil {
701			v.Logger.Warnf("Node %d got %s from %d, but signature is invalid, error: %v", v.SelfID, signedViewDataToString(svd), sender, vcValSigErr)
702			return false, 0
703		}
704	
705		return true, lastDecisionMD.LatestSequence
706	}
707	
708	func (v *ViewChanger) extractCurrentSequence() (uint64, *protos.Proposal) {
709		myMetadata := &protos.ViewMetadata{}
710		myLastDesicion, _ := v.Checkpoint.Get()
711		if myLastDesicion.Metadata == nil {
712			return 0, myLastDesicion
713		}
714		if err := proto.Unmarshal(myLastDesicion.Metadata, myMetadata); err != nil {
715			v.Logger.Panicf("Node %d is unable to unmarshal its own last decision metadata from checkpoint, err: %v", v.SelfID, err)
716		}
717		return myMetadata.LatestSequence, myLastDesicion
718	}
719	
720	// ValidateLastDecision validates the given decision, and returns its sequence when valid
721	func ValidateLastDecision(vd *protos.ViewData, quorum int, n uint64, verifier api.Verifier) (lastSequence uint64, err error) {
722		if vd.LastDecision == nil {
723			return 0, errors.New("the last decision is not set")
724		}
725		if vd.LastDecision.Metadata == nil {
726			// This is a genesis proposal, there are no signatures to validate, so we return at this point
727			return 0, nil
728		}
729		md := &protos.ViewMetadata{}
730		if err = proto.Unmarshal(vd.LastDecision.Metadata, md); err != nil {
731			return 0, fmt.Errorf("unable to unmarshal last decision metadata, err: %w", err)
732		}
733		if md.ViewId >= vd.NextView {
734			return 0, fmt.Errorf("last decision view %d is greater or equal to requested next view %d", md.ViewId, vd.NextView)
735		}
736		numSigs := len(vd.LastDecisionSignatures)
737		if numSigs < quorum {
738			return 0, fmt.Errorf("there are only %d last decision signatures", numSigs)
739		}
740		nodesMap := make(map[uint64]struct{}, n)
741		validSig := 0
742		for _, sig := range vd.LastDecisionSignatures {
743			if _, exist := nodesMap[sig.Signer]; exist {
744				continue // seen signature from this node already
745			}
746			nodesMap[sig.Signer] = struct{}{}
747			signature := types.Signature{
748				ID:    sig.Signer,
749				Value: sig.Value,
750				Msg:   sig.Msg,
751			}
752			proposal := types.Proposal{
753				Header:               vd.LastDecision.Header,
754				Payload:              vd.LastDecision.Payload,
755				Metadata:             vd.LastDecision.Metadata,
756				VerificationSequence: int64(vd.LastDecision.VerificationSequence),
757			}
758			if _, err = verifier.VerifyConsenterSig(signature, proposal); err != nil {
759				return 0, fmt.Errorf("last decision signature is invalid, error: %w", err)
760			}
761			validSig++
762		}
763		if validSig < quorum {
764			return 0, fmt.Errorf("there are only %d valid last decision signatures", validSig)
765		}
766		return md.LatestSequence, nil
767	}
