769	// ValidateInFlight validates the given in-flight proposal
770	func ValidateInFlight(inFlightProposal *protos.Proposal, lastSequence uint64) error {
771		if inFlightProposal == nil {
772			return nil
773		}
774		if inFlightProposal.Metadata == nil {
775			return errors.New("in flight proposal metadata is nil")
776		}
777		inFlightMetadata := &protos.ViewMetadata{}
778		if err := proto.Unmarshal(inFlightProposal.Metadata, inFlightMetadata); err != nil {
779			return fmt.Errorf("unable to unmarshal the in flight proposal metadata, err: %w", err)
780		}
781		if inFlightMetadata.LatestSequence != lastSequence+1 {
782			return fmt.Errorf("the in flight proposal sequence is %d while the last decision sequence is %d", inFlightMetadata.LatestSequence, lastSequence)
783		}
784		return nil
785	}
