787	func (v *ViewChanger) processViewDataMsg() {
788		if len(v.viewDataMsgs.voted) < v.quorum {
789			return // need enough (quorum) data to continue
790		}
791		v.Logger.Debugf("Node %d got a quorum of viewData messages", v.SelfID)
792		ok, _, _, err := CheckInFlight(v.getViewDataMessages(), v.f, v.quorum, v.N, v.Verifier)
793		if err != nil {
794			v.Logger.Panicf("Node %d checked the in flight and it got an error: %v", v.SelfID, err)
795		}
796		if !ok {
797			v.Logger.Debugf("Node %d checked the in flight and it was invalid", v.SelfID)
798			return
799		}
800		v.Logger.Debugf("Node %d checked the in flight and it was valid", v.SelfID)
801		// create the new view message
802		signedMsgs := make([]*protos.SignedViewData, 0)
803		myMsg := v.prepareViewDataMsg()                      // since it might have changed by now
804		signedMsgs = append(signedMsgs, myMsg.GetViewData()) // leader's message will always be the first
805		close(v.viewDataMsgs.votes)
806		for vt := range v.viewDataMsgs.votes {
807			if vt.sender == v.SelfID {
808				continue // ignore my old message
809			}
810			signedMsgs = append(signedMsgs, vt.GetViewData())
811		}
812		msg := &protos.Message{
813			Content: &protos.Message_NewView{
814				NewView: &protos.NewView{
815					SignedViewData: signedMsgs,
816				},
817			},
818		}
819		v.Logger.Debugf("Node %d is broadcasting a new view msg", v.SelfID)
820		v.Comm.BroadcastConsensus(msg)
821		v.Logger.Debugf("Node %d sent a new view msg to self", v.SelfID)
822		v.processMsg(v.SelfID, msg) // also send to myself // TODO consider not reprocessing this message
823		v.viewDataMsgs.clear(v.N)
824		v.Logger.Debugf("Node %d sent a new view msg", v.SelfID)
825	}
826	
827	// returns view data messages included in votes
828	func (v *ViewChanger) getViewDataMessages() []*protos.ViewData {
829		var messages []*protos.ViewData
830		for range len(v.viewDataMsgs.votes) {
831			vt := <-v.viewDataMsgs.votes
832			vd := &protos.ViewData{}
833			if err := proto.Unmarshal(vt.GetViewData().RawViewData, vd); err != nil {
834				v.Logger.Panicf("Node %d was unable to unmarshal viewData message, error: %v", v.SelfID, err)
835			}
836			messages = append(messages, vd)
837			v.viewDataMsgs.votes <- vt
838		}
839		return messages
840	}
