842	type possibleProposal struct {
843		proposal    *protos.Proposal
844		preprepared int
845		noArgument  int
846	}
847	
848	type proposalAndMetadata struct {
849		proposal *protos.Proposal
850		metadata *protos.ViewMetadata
851	}
852	
853	// CheckInFlight checks if there is an in-flight proposal that needs to be decided on (because a node might decided on it already)
854	func CheckInFlight(messages []*protos.ViewData, f int, quorum int, n uint64, verifier api.Verifier) (ok, noInFlight bool, inFlightProposal *protos.Proposal, err error) {
855		expectedSequence := maxLastDecisionSequence(messages) + 1
856		possibleProposals := make([]*possibleProposal, 0)
857		proposalsAndMetadata := make([]*proposalAndMetadata, 0)
858		noInFlightCount := 0
859		for _, vd := range messages {
860			if vd.InFlightProposal == nil { // there is no in flight proposal here
861				noInFlightCount++
862				proposalsAndMetadata = append(proposalsAndMetadata, &proposalAndMetadata{nil, nil})
863				continue
864			}
865	
866			if vd.InFlightProposal.Metadata == nil { // should have been validated earlier
867				return false, false, nil, errors.New("node has a view data message where the in flight proposal metadata is nil")
868			}
869	
870			inFlightMetadata := &protos.ViewMetadata{}
871			if err = proto.Unmarshal(vd.InFlightProposal.Metadata, inFlightMetadata); err != nil { // should have been validated earlier
872				return false, false, nil, fmt.Errorf("node was unable to unmarshal the in flight proposal metadata, error: %w", err)
873			}
874	
875			proposalsAndMetadata = append(proposalsAndMetadata, &proposalAndMetadata{vd.InFlightProposal, inFlightMetadata})
876	
877			if inFlightMetadata.LatestSequence != expectedSequence { // the in flight proposal sequence is not as expected
878				noInFlightCount++
879				continue
880			}
881	
882			// now the in flight proposal is with the expected sequence
883			// find possible proposals
884	
885			if !vd.InFlightPrepared { // no prepared so isn't a possible proposal
886				noInFlightCount++
887				continue
888			}
889	
890			// this proposal is prepared and so it is possible
891			alreadyExists := false
892			for _, p := range possibleProposals {
893				if proto.Equal(p.proposal, vd.InFlightProposal) {
894					alreadyExists = true
895					break
896				}
897			}
898			if !alreadyExists {
899				// this is not a proposal we have seen before
900				possibleProposals = append(possibleProposals, &possibleProposal{proposal: vd.InFlightProposal})
901			}
902		}
903	
904		// fill out info on all possible proposals
905		for _, prop := range proposalsAndMetadata {
906			for _, possible := range possibleProposals {
907				if prop.proposal == nil {
908					possible.noArgument++
909					continue
910				}
911	
912				if prop.metadata.LatestSequence != expectedSequence {
913					possible.noArgument++
914					continue
915				}
916	
917				if proto.Equal(prop.proposal, possible.proposal) {
918					possible.noArgument++
919					possible.preprepared++
920				}
921			}
922		}
923	
924		// see if there is an in flight proposal that is agreed on
925		agreed := -1
926		for i, possible := range possibleProposals {
927			if possible.preprepared < f+1 { // condition A2 doesn't hold
928				continue
929			}
930			if possible.noArgument < quorum { // condition A1 doesn't hold
931				continue
932			}
933			agreed = i
934			break
935		}
936	
937		// condition A holds
938		if agreed != -1 {
939			return true, false, possibleProposals[agreed].proposal, nil
940		}
941	
942		// condition B holds
943		if noInFlightCount >= quorum { // there is a quorum of messages that support that there is no prepared in flight proposal
944			return true, true, nil, nil
945		}
946	
947		return false, false, nil, nil
948	}
949	
950	// returns the highest sequence of a last decision within the given view data messages
951	func maxLastDecisionSequence(messages []*protos.ViewData) uint64 {
952		max := uint64(0)
953		for _, vd := range messages {
954			if vd.LastDecision == nil {
955				panic("The last decision is not set")
956			}
957			if vd.LastDecision.Metadata == nil { // this is a genesis proposal
958				continue
959			}
960			md := &protos.ViewMetadata{}
961			if err := proto.Unmarshal(vd.LastDecision.Metadata, md); err != nil {
962				panic(fmt.Sprintf("Unable to unmarshal the last decision metadata, err: %v", err))
963			}
964			if md.LatestSequence > max {
965				max = md.LatestSequence
966			}
967		}
968		return max
969	}
