971	func (v *ViewChanger) validateNewViewMsg(msg *protos.NewView) (valid bool, sync bool, deliver bool) {
972		signed := msg.GetSignedViewData()
973		nodesMap := make(map[uint64]struct{}, v.N)
974		validViewDataMsgs := 0
975		mySequence, myLastDecision := v.extractCurrentSequence()
976		for _, svd := range signed {
977			if _, exist := nodesMap[svd.Signer]; exist {
978				continue // seen data from this node already
979			}
980			nodesMap[svd.Signer] = struct{}{}
981	
982			vd := &protos.ViewData{}
983			if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
984				v.Logger.Errorf("Node %d was unable to unmarshal viewData from the newView message, error: %v", v.SelfID, err)
985				return false, false, false
986			}
987	
988			if vd.NextView != v.currView {
989				v.Logger.Warnf("Node %d is processing newView message, but nextView of %s is %d, while the currView is %d", v.SelfID, signedViewDataToString(svd), vd.NextView, v.currView)
990				return false, false, false
991			}
992	
993			if vd.LastDecision == nil {
994				v.Logger.Warnf("Node %d is processing newView message, but the last decision of %s is not set", v.SelfID, signedViewDataToString(svd))
995				return false, false, false
996			}
997	
998			// Begin to check the last decision within the view data message.
999			//
1000			// This node might be ahead, in which case it might not have the right config to validate
1001			// the decision and signatures, and so the view data message is deemed invalid.
1002			//
1003			// If this node is too far behind then it needs to sync.
1004			// No validation can be done since it might not have the appropriate config.
1005			//
1006			// If the last decision sequence is equal to this node's sequence then we check that the decisions are equal.
1007			// However, we cannot validate the decision signatures since this last decision might have been a reconfig.
1008			//
1009			// Lastly, this node is behind by one sequence, and so it validates the decision and delivers it.
1010			// Only after delivery the message signature is verified, again since this decision might have been a reconfig.
1011	
1012			if vd.LastDecision.Metadata == nil { // this is a genesis proposal
1013				if mySequence > 0 {
1014					// can't validate the signature since I am ahead
1015					if err := ValidateInFlight(vd.InFlightProposal, 0); err != nil {
1016						v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1017						return false, false, false
1018					}
1019					validViewDataMsgs++
1020					continue
1021				}
1022				if err := v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
1023					v.Logger.Warnf("Node %d is processing newView message, but signature of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1024					return false, false, false
1025				}
1026				if err := ValidateInFlight(vd.InFlightProposal, 0); err != nil {
1027					v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1028					return false, false, false
1029				}
1030				validViewDataMsgs++
1031				continue
1032			}
1033	
1034			lastDecisionMD := &protos.ViewMetadata{}
1035			if err := proto.Unmarshal(vd.LastDecision.Metadata, lastDecisionMD); err != nil {
1036				v.Logger.Warnf("Node %d is processing newView message, but was unable to unmarshal the last decision of %s, err: %v", v.SelfID, signedViewDataToString(svd), err)
1037				return false, false, false
1038			}
1039			if lastDecisionMD.ViewId >= vd.NextView {
1040				v.Logger.Warnf("Node %d is processing newView message, but the last decision view %d is greater or equal to requested next view %d of %s", v.SelfID, lastDecisionMD.ViewId, vd.NextView, signedViewDataToString(svd))
1041				return false, false, false
1042			}
1043	
1044			if lastDecisionMD.LatestSequence > mySequence+1 { // this is a decision in the future, can't verify it and should sync
1045				v.Synchronizer.Sync() // TODO check if I managed to sync to latest decision, revalidate new view, and join the other nodes
1046				return true, true, false
1047			}
1048	
1049			if lastDecisionMD.LatestSequence < mySequence { // this is a decision in the past
1050				// can't validate the signature since I am ahead
1051				if err := ValidateInFlight(vd.InFlightProposal, lastDecisionMD.LatestSequence); err != nil {
1052					v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1053					return false, false, false
1054				}
1055				validViewDataMsgs++
1056				continue
1057			}
1058	
1059			if lastDecisionMD.LatestSequence == mySequence { // just make sure that we have the same last decision, can't verify the signatures of this last decision since this might have been a reconfiguration
1060				// the signature on this message can be verified
1061				if err := v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
1062					v.Logger.Warnf("Node %d is processing newView message, but signature of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1063					return false, false, false
1064				}
1065	
1066				// compare the last decision itself
1067				if !proto.Equal(vd.LastDecision, myLastDecision) {
1068					v.Logger.Warnf("Node %d is processing newView message, but the last decision of %s is with the same sequence but is not equal", v.SelfID, signedViewDataToString(svd))
1069					return false, false, false
1070				}
1071	
1072				if err := ValidateInFlight(vd.InFlightProposal, lastDecisionMD.LatestSequence); err != nil {
1073					v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1074					return false, false, false
1075				}
1076	
1077				validViewDataMsgs++
1078				continue
1079			}
1080	
1081			if lastDecisionMD.LatestSequence != mySequence+1 {
1082				v.Logger.Warnf("Node %d is processing newView message, but the last decision sequence is not equal to this node's sequence + 1", v.SelfID)
1083				return false, false, false
1084			}
1085	
1086			_, err := ValidateLastDecision(vd, v.quorum, v.N, v.Verifier)
1087			if err != nil {
1088				v.Logger.Warnf("Node %d is processing newView message, but the last decision of %s is invalid, reason: %v", v.SelfID, signedViewDataToString(svd), err)
1089				return false, false, false
1090			}
1091	
1092			proposal := types.Proposal{
1093				Header:               vd.LastDecision.Header,
1094				Metadata:             vd.LastDecision.Metadata,
1095				Payload:              vd.LastDecision.Payload,
1096				VerificationSequence: int64(vd.LastDecision.VerificationSequence),
1097			}
1098			signatures := make([]types.Signature, 0)
1099			for _, sig := range vd.LastDecisionSignatures {
1100				signature := types.Signature{
1101					ID:    sig.Signer,
1102					Value: sig.Value,
1103					Msg:   sig.Msg,
1104				}
1105				signatures = append(signatures, signature)
1106			}
1107			v.deliverDecision(proposal, signatures)
1108	
1109			select { // if there was a delivery with a reconfig we need to stop here before verify signature
1110			case <-v.stopChan:
1111				return false, false, false
1112			default:
1113			}
1114	
1115			if err = v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
1116				v.Logger.Warnf("Node %d is processing newView message, but signature of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1117				return false, false, false
1118			}
1119	
1120			if err = ValidateInFlight(vd.InFlightProposal, lastDecisionMD.LatestSequence); err != nil {
1121				v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1122				return false, false, false
1123			}
1124	
1125			return true, false, true
1126		}
1127	
1128		if validViewDataMsgs < v.quorum {
1129			v.Logger.Warnf("Node %d is processing newView message, but there was only %d valid view data messages while the quorum is %d", v.SelfID, validViewDataMsgs, v.quorum)
1130			return false, false, false
1131		}
1132	
1133		v.Logger.Debugf("Node %d found a quorum of valid view data messages within the new view message", v.SelfID)
1134		return true, false, false
1135	}
1136	
1137	func (v *ViewChanger) extractViewDataMessages(msg *protos.NewView) []*protos.ViewData {
1138		signed := msg.GetSignedViewData()
1139		vds := make([]*protos.ViewData, 0)
1140		for _, svd := range signed {
1141			vd := &protos.ViewData{}
1142			if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
1143				v.Logger.Panicf("Node %d was unable to unmarshal viewData from the newView message, error: %v", v.SelfID, err)
1144			}
1145			vds = append(vds, vd)
1146		}
1147		return vds
1148	}
1149	
1150	func (v *ViewChanger) processNewViewMsg(msg *protos.NewView) {
1151		valid, calledSync, calledDeliver := v.validateNewViewMsg(msg)
1152		for calledDeliver {
1153			v.Logger.Debugf("Node %d is processing a newView message, and delivered a proposal", v.SelfID)
1154			valid, calledSync, calledDeliver = v.validateNewViewMsg(msg)
1155		}
1156		if !valid {
1157			v.Logger.Warnf("Node %d is processing a newView message, but the message is invalid", v.SelfID)
1158			return
1159		}
1160		if calledSync {
1161			v.Logger.Debugf("Node %d is processing a newView message, and requested a sync", v.SelfID)
1162			return
1163		}
1164	
1165		ok, noInFlight, inFlightProposal, err := CheckInFlight(v.extractViewDataMessages(msg), v.f, v.quorum, v.N, v.Verifier)
1166		if err != nil {
1167			v.Logger.Panicf("The check of the in flight proposal by node %d returned an error: %v", v.SelfID, err)
1168		}
1169		if !ok {
1170			v.Logger.Debugf("The check of the in flight proposal by node %d did not pass", v.SelfID)
1171			return
1172		}
1173	
1174		if !noInFlight && !v.commitInFlightProposal(inFlightProposal) {
1175			v.Logger.Warnf("Node %d was unable to commit the in flight proposal, not changing the view", v.SelfID)
1176			return
1177		}
1178	
1179		mySequence, _ := v.extractCurrentSequence()
1180	
1181		newViewToSave := &protos.SavedMessage{
1182			Content: &protos.SavedMessage_NewView{
1183				NewView: &protos.ViewMetadata{
1184					ViewId:         v.currView,
1185					LatestSequence: mySequence,
1186				},
1187			},
1188		}
1189		if err = v.State.Save(newViewToSave); err != nil {
1190			v.Logger.Panicf("Failed to save message to state, error: %v", err)
1191		}
1192	
1193		select { // if there was a delivery or sync with a reconfig when committing the in-flight proposal we should stop
1194		case <-v.stopChan:
1195			return
1196		default:
1197		}
1198	
1199		v.realView = v.currView
1200		v.MetricsViewChange.RealView.Set(float64(v.realView))
1201		v.nvs.clear()
1202		v.Controller.ViewChanged(v.currView, mySequence+1)
1203		if TLATrace != nil {
1204			TLATrace.Emit(map[string]interface{}{
1205				"event":        "enter_new_view",
1206				"node":         v.SelfID,
1207				"view":         v.currView,
1208				"proposal_seq": mySequence + 1,
1209			})
1210		}
1211	
1212		v.RequestsTimer.RestartTimers()
1213		v.checkTimeout = false
1214		v.backOffFactor = 1 // reset
1215	}
1216	
1217	func (v *ViewChanger) deliverDecision(proposal types.Proposal, signatures []types.Signature) {
1218		v.Logger.Debugf("Delivering to app from deliverDecision the last decision proposal")
1219		reconfig := v.Application.Deliver(proposal, signatures)
1220		if reconfig.InLatestDecision {
1221			v.close()
1222		}
1223		v.Logger.Debugf("Delivering end to app from deliverDecision the last decision proposal")
1224	
1225		requests := v.Verifier.RequestsFromProposal(proposal)
1226		for _, reqInfo := range requests {
1227			if err := v.RequestsTimer.RemoveRequest(reqInfo); err != nil {
1228				v.Logger.Warnf("Error during remove of request %s from the pool, err: %v", reqInfo, err)
1229			}
1230		}
1231		v.Pruner.MaybePruneRevokedRequests()
1232	}
1233	
1234	func (v *ViewChanger) commitInFlightProposal(proposal *protos.Proposal) (success bool) {
1235		myLastDecision, _ := v.Checkpoint.Get()
1236		if proposal == nil {
1237			v.Logger.Panicf("The in flight proposal is nil")
1238			return
1239		}
1240		proposalMD := &protos.ViewMetadata{}
1241		if err := proto.Unmarshal(proposal.Metadata, proposalMD); err != nil {
1242			v.Logger.Panicf("Node %d is unable to unmarshal the in flight proposal metadata, err: %v", v.SelfID, err)
1243		}
1244	
1245		if myLastDecision.Metadata != nil { // if metadata is nil then I am at genesis proposal and I should commit the in flight proposal anyway
1246			lastDecisionMD := &protos.ViewMetadata{}
1247			if err := proto.Unmarshal(myLastDecision.Metadata, lastDecisionMD); err != nil {
1248				v.Logger.Panicf("Node %d is unable to unmarshal its own last decision metadata from checkpoint, err: %v", v.SelfID, err)
1249			}
1250			if lastDecisionMD.LatestSequence == proposalMD.LatestSequence {
1251				v.Logger.Debugf("Node %d already decided on sequence %d and so it will not commit the in flight proposal with the same sequence", v.SelfID, lastDecisionMD.LatestSequence)
1252				v.Logger.Debugf("Node %d is comparing its last decision with the in flight proposal with the same sequence %d", v.SelfID, lastDecisionMD.LatestSequence)
1253				if !proto.Equal(myLastDecision, proposal) {
1254					v.Logger.Warnf("Node %d compared its last decision with the in flight proposal, which has the same sequence, but they are not equal", v.SelfID)
1255					return false
1256				}
1257				return true // I already decided on the in flight proposal
1258			}
1259			if lastDecisionMD.LatestSequence != proposalMD.LatestSequence-1 {
1260				v.Logger.Panicf("Node %d got an in flight proposal with sequence %d while its last decision was on sequence %d", v.SelfID, proposalMD.LatestSequence, lastDecisionMD.LatestSequence)
1261			}
1262		}
1263	
1264		v.Logger.Debugf("Node %d is creating a view %d for the in flight proposal", v.SelfID, proposalMD.ViewId)
1265	
1266		inFlightViewNum := proposalMD.ViewId
1267		inFlightViewLatestSeq := proposalMD.LatestSequence
1268	
1269		v.inFlightViewLock.Lock()
1270		inFlightView := &View{
1271			RetrieveCheckpoint: v.Checkpoint.Get,
1272			DecisionsPerLeader: v.DecisionsPerLeader,
1273			SelfID:             v.SelfID,
1274			N:                  v.N,
1275			NodesList:          v.NodesList,
1276			Number:             inFlightViewNum,
1277			LeaderID:           v.SelfID, // so that no byzantine leader will cause a complain
1278			Quorum:             v.quorum,
1279			Decider:            v,
1280			FailureDetector:    v,
1281			Sync:               v,
1282			Logger:             v.Logger,
1283			Comm:               v.Comm,
1284			Verifier:           v.Verifier,
1285			Signer:             v.Signer,
1286			ProposalSequence:   inFlightViewLatestSeq,
1287			State:              v.State,
1288			InMsgQSize:         v.InMsqQSize,
1289			ViewSequences:      v.ViewSequences,
1290			Phase:              PREPARED,
1291			MetricsBlacklist:   v.MetricsBlacklist,
1292			MetricsView:        v.MetricsView,
1293		}
1294		inFlightView.MetricsView.ViewNumber.Set(float64(inFlightView.Number))
1295		inFlightView.MetricsView.LeaderID.Set(float64(inFlightView.LeaderID))
1296		inFlightView.MetricsView.ProposalSequence.Set(float64(inFlightView.ProposalSequence))
1297		inFlightView.MetricsView.DecisionsInView.Set(float64(inFlightView.DecisionsInView))
1298		inFlightView.MetricsView.Phase.Set(float64(inFlightView.Phase))
1299	
1300		v.inFlightView = inFlightView
1301		v.inFlightView.inFlightProposal = &types.Proposal{
1302			VerificationSequence: int64(proposal.VerificationSequence),
1303			Metadata:             proposal.Metadata,
1304			Payload:              proposal.Payload,
1305			Header:               proposal.Header,
1306		}
1307		v.inFlightView.myProposalSig = v.Signer.SignProposal(*v.inFlightView.inFlightProposal, nil)
1308		v.inFlightView.lastBroadcastSent = &protos.Message{
1309			Content: &protos.Message_Commit{
1310				Commit: &protos.Commit{
1311					View:   v.inFlightView.Number,
1312					Digest: v.inFlightView.inFlightProposal.Digest(),
1313					Seq:    v.inFlightView.ProposalSequence,
1314					Signature: &protos.Signature{
1315						Signer: v.inFlightView.myProposalSig.ID,
1316						Value:  v.inFlightView.myProposalSig.Value,
1317						Msg:    v.inFlightView.myProposalSig.Msg,
1318					},
1319				},
1320			},
1321		}
1322	
1323		v.Logger.Debugf("Waiting two ticks before starting in-flight view")
1324		<-v.Ticker
1325		<-v.Ticker
1326	
1327		inFlightView.Start()
1328		defer inFlightView.Abort()
1329	
1330		v.inFlightViewLock.Unlock()
1331	
1332		v.Logger.Debugf("Node %d started a view %d for the in flight proposal", v.SelfID, v.inFlightView.Number)
1333	
1334		// wait for view to finish or time out
1335		for {
1336			select {
1337			case <-v.inFlightDecideChan:
1338				v.Logger.Infof("In-flight view %d with latest sequence %d has committed a decision", inFlightViewNum, inFlightViewLatestSeq)
1339				return true
1340			case <-v.inFlightSyncChan:
1341				v.Logger.Infof("In-flight view %d with latest sequence %d has asked to sync", inFlightViewNum, inFlightViewLatestSeq)
1342				return false
1343			case now := <-v.Ticker:
1344				v.lastTick = now
1345				if v.checkIfTimeout(now) {
1346					v.Logger.Infof("Timeout expired waiting on In-flight %d with latest sequence view to commit %d", inFlightViewNum, inFlightViewLatestSeq)
1347					return false
1348				}
1349			case <-v.stopChan:
1350				v.Logger.Infof("View changer was instructed to stop")
1351				return false
1352			}
1353		}
1354	}
1355	
1356	// Decide delivers to the application and informs the view changer after delivery
1357	func (v *ViewChanger) Decide(proposal types.Proposal, signatures []types.Signature, requests []types.RequestInfo) {
1358		v.inFlightView.stop()
1359		v.Logger.Debugf("Delivering to app from Decide the last decision proposal")
1360		reconfig := v.Application.Deliver(proposal, signatures)
1361		if reconfig.InLatestDecision {
1362			v.close()
1363		}
1364		v.Logger.Debugf("Delivering end to app from Decide the last decision proposal")
1365	
1366		for _, reqInfo := range requests {
1367			if err := v.RequestsTimer.RemoveRequest(reqInfo); err != nil {
1368				v.Logger.Warnf("Error during remove of request %s from the pool, err: %v", reqInfo, err)
1369			}
1370		}
1371		v.Pruner.MaybePruneRevokedRequests()
1372	
1373		select {
1374		case v.inFlightDecideChan <- struct{}{}:
1375			return
1376		case <-v.stopChan:
1377			return
1378		}
1379	}
1380	
1381	// Complain panics when a view change is requested
1382	func (v *ViewChanger) Complain(viewNum uint64, stopView bool) {
1383		v.Logger.Panicf("Node %d has complained while in the view for the in flight proposal", v.SelfID)
1384	}
1385	
1386	// Sync calls the synchronizer and informs the view changer of the sync
1387	func (v *ViewChanger) Sync() {
1388		// the in flight proposal view asked to sync
1389		v.Logger.Debugf("Node %d is calling sync because the in flight proposal view has asked to sync", v.SelfID)
1390		v.Synchronizer.Sync()
1391		v.inFlightSyncChan <- struct{}{}
1392	}
1393	
1394	// HandleViewMessage passes a message to the in flight proposal view if applicable
1395	func (v *ViewChanger) HandleViewMessage(sender uint64, m *protos.Message) {
1396		v.inFlightViewLock.RLock()
1397		defer v.inFlightViewLock.RUnlock()
1398		if view := v.inFlightView; view != nil {
1399			v.Logger.Debugf("Node %d is passing a message to the in flight view", v.SelfID)
1400			view.HandleMessage(sender, m)
1401		}
1402	}
1403	
1404	func (v *ViewChanger) blacklist() []uint64 {
1405		prop, _ := v.Checkpoint.Get()
1406		md := &protos.ViewMetadata{}
1407		if err := proto.Unmarshal(prop.Metadata, md); err != nil {
1408			v.Logger.Panicf("Failed unmarshalling metadata: %v", err)
1409		}
1410		return md.BlackList
1411	}
1412

